/** Generated from retained local Z-Image V21 stemless blossom heads. */
export type GardenBlossomTone = 'blue' | 'pink'
/** One stemless generated blossom that can attach directly to a vine. */
export interface GardenBlossomHead { readonly name: string; readonly tone: GardenBlossomTone; readonly art: string }

/** Reviewed blue and pink stemless blossom material set. */
export const GARDEN_BLOSSOM_HEADS: readonly GardenBlossomHead[] = [
  { name: 'powder-blue-poppy', tone: 'blue', art: 'data:image/webp;base64,' },
  { name: 'sapphire-cornflower', tone: 'blue', art: 'data:image/webp;base64,' },
  { name: 'periwinkle-cosmos', tone: 'blue', art: 'data:image/webp;base64,' },
  { name: 'blue-hydrangea-head', tone: 'blue', art: 'data:image/webp;base64,' },
  { name: 'blush-peony', tone: 'pink', art: 'data:image/webp;base64,' },
  { name: 'rose-camellia', tone: 'pink', art: 'data:image/webp;base64,' },
  { name: 'pink-cosmos', tone: 'pink', art: 'data:image/webp;base64,' },
  { name: 'berry-ranunculus', tone: 'pink', art: 'data:image/webp;base64,' },
] as const

/** Blue blossom subset used for sparse large accents. */
export const GARDEN_BLUE_BLOSSOM_HEADS = GARDEN_BLOSSOM_HEADS.filter(blossom => blossom.tone === 'blue')
